317	    /// [`Self::resolve`] for an already-parsed selector.
318	    pub fn resolve_id(&self, id: &PackageId) -> Result<PackageId, GraphError> {
319	        match id {
320	            PackageId::Prefixed { ecosystem, name } => self
321	                .native
322	                .get(&(*ecosystem, name.clone()))
323	                .cloned()
324	                .ok_or_else(|| GraphError::UnknownPackage { id: id.clone() }),
325	            PackageId::Bare(name) => {
326	                let candidates: BTreeSet<PackageId> = self
327	                    .native
328	                    .iter()
329	                    .filter(|((_, n), _)| n == name)
330	                    .map(|(_, registered)| registered.clone())
331	                    .collect();
332	                match candidates.len() {
333	                    0 => Err(GraphError::UnknownPackage { id: id.clone() }),
334	                    1 => Ok(candidates.into_iter().next().expect("len checked above")),
335	                    _ => Err(GraphError::AmbiguousName {
336	                        name: name.clone(),
337	                        candidates: candidates.into_iter().collect(),
338	                    }),
339	                }
340	            }
341	        }
342	    }
