 30	/// resolution path -- rather than a bare `matches()` loop, so a changeset
 31	/// entry naming a bare package that exists in two or more ecosystems (e.g.
 32	/// `cargo/foo` and `npm/foo`) is never silently attached to every matching
 33	/// package. An unknown or ambiguous entry is skipped here rather than
 34	/// hard-erroring: `changeset_wellformedness_diagnostics` reports both cases
 35	/// as an Error-severity diagnostic instead.
 36	fn resolve_pending_changesets<'a>(
 37	    packages: impl Iterator<Item = &'a Package> + Clone,
 38	    loaded_changesets: &[LoadedChangeset],
 39	) -> PendingChangesets {
 40	    let mut pending: PendingChangesets = BTreeMap::new();
 41	    for lc in loaded_changesets {
 42	        for entry in &lc.changeset.entries {
 43	            let Ok(entry_id) = PackageId::parse(&entry.name) else {
 44	                continue;
 45	            };
 46	            let Ok(Some(resolved)) = entry_id.resolve_unique(packages.clone(), |p| &p.id) else {
 47	                continue;
 48	            };
 49	            let name = lc
 50	                .path
 51	                .file_stem()
 52	                .and_then(|s| s.to_str())
 53	                .unwrap_or("unknown")
 54	                .to_string();
 55	            let state = pending.entry(resolved.id.clone()).or_default();
 56	            state.0.push(name);
 57	            state.1 = match (state.1, entry.severity) {
 58	                (None, s) => Some(s),
 59	                (Some(cur), s) => Some(cur.max(s)),
 60	            };
 61	        }
 62	    }
 63	    pending
 64	}
