300	    /// The one selector resolver: resolves a user- or config-typed package
301	    /// selector (`eco:name`, `eco/name`, or a bare name) against registered
302	    /// native manifest names.
303	    ///
304	    /// A qualified selector is an exact `(ecosystem, native name)` lookup: no
305	    /// match is `E102` ([`GraphError::UnknownPackage`]), regardless of what a
306	    /// different ecosystem calls itself. A bare selector searches every
307	    /// ecosystem's native names: no match is `E102`; more than one distinct
308	    /// package answering to that name in different ecosystems is `E103`
309	    /// ([`GraphError::AmbiguousName`]). Resolving by any registered native
310	    /// name -- not just a package's primary/display name -- is what lets a
311	    /// dual-manifest package be named by either of its manifests' names.
312	    pub fn resolve(&self, selector: &str) -> Result<PackageId, GraphError> {
313	        let id = PackageId::parse(selector).unwrap_or_else(|_| PackageId::Bare(selector.to_string()));
314	        self.resolve_id(&id)
315	    }
