344	    /// True when `selector` (an ecosystem-qualified or bare configured
345	    /// package identity, e.g. from `[[release.artifact]]` or
346	    /// `product-package`) resolves to `candidate`.
347	    ///
348	    /// The single replacement for the `selector.matches(&candidate) &&
349	    /// selector.ecosystem() == Some(candidate_ecosystem)` guard that was
350	    /// hand-rolled at every config-selector call site: `PackageId::matches`
351	    /// alone treats a bare id as an ecosystem wildcard, so a qualified
352	    /// selector for one ecosystem's package would otherwise match a
353	    /// same-named package in another.
354	    pub fn identifies(&self, selector: &PackageId, candidate: &PackageId) -> bool {
355	        self.resolve_id(selector).is_ok_and(|resolved| &resolved == candidate)
356	    }
