358	    pub fn resolve_human(&self, name: &str, siblings: &[PackageId]) -> Result<PackageId, GraphError> {
359	        if let Ok(PackageId::Prefixed { ecosystem, name: n }) = PackageId::parse(name) {
360	            if let Some(id) = self.prefixed.get(&(ecosystem, n)) {
361	                return Ok(id.clone());
362	            }
363	        }
364	
365	        if let Some(id) = self.bare.get(name) {
366	            return Ok(id.clone());
367	        }
368	
369	        let mut candidates = Vec::new();
370	        for ((_eco, n), id) in &self.prefixed {
371	            if n == name {
372	                candidates.push(id.clone());
373	            }
374	        }
375	
376	        if candidates.len() == 1 {
377	            return Ok(candidates[0].clone());
378	        }
379	
380	        if candidates.len() > 1 && !siblings.is_empty() {
381	            for sib in siblings {
382	                for cand in &candidates {
383	                    if cand.ecosystem() == sib.ecosystem() {
384	                        return Ok(cand.clone());
385	                    }
386	                }
387	            }
388	        }
389	
390	        if candidates.is_empty() {
391	            Err(GraphError::UnknownPackage {
392	                id: PackageId::parse(name).unwrap_or_else(|_| PackageId::Bare(name.to_string())),
393	            })
394	        } else {
395	            Err(GraphError::AmbiguousName {
396	                name: name.to_string(),
397	                candidates,
398	            })
399	        }
400	    }
