402	    /// Look up a package by its native (manifest-declared) name.
403	    ///
404	    /// Python names use PEP 503 equivalence; other ecosystems use exact names.
405	    /// If no name matches within the ecosystem -- a
406	    /// package in one ecosystem depending on a different ecosystem's
407	    /// package by bare name (e.g. an npm package listing a cargo crate)
408	    /// -- falls back to scanning all ecosystems for `name`.
409	    ///
410	    /// Fallback finds exactly one match: returns it. Finds more than one
155	    }
156	}
