158	/// Resolves a release tag name to the commit SHA it points at, so that
159	/// severity inference can be scoped to `since..HEAD` instead of walking the
160	/// entire history on every `aggregate()`-driven command.
161	///
162	/// Any failure to resolve the tag (missing, unborn repo, etc.) degrades to
163	/// `None`, which callers treat as "infer over full history".
164	fn resolve_since(git: &GitAccess<'_>, tag_name: &str) -> Option<CommitSha> {
165	    git.resolve_commit(tag_name).ok().flatten()
