168	/// Resolves a changeset entry's or `--package` argument's parsed `PackageId`
169	/// against the packages in the graph, through [`IdentityIndex::resolve_id`] --
170	/// the one selector resolver, not a `PackageId::matches` scan (which treats a
171	/// Bare query as an ecosystem wildcard and would wrongly let a qualified
172	/// selector for one ecosystem select a same-named package in another).
173	///
174	/// `Ok(None)`: no match (unknown package, reported separately by
175	/// `validate`). `Ok(Some(pkg))`: unambiguous. `Err(AmbiguousName)`: two or
176	/// more matches (E103).
177	pub(crate) fn resolve_target_package<'a>(
178	    packages: impl Iterator<Item = &'a Package>,
179	    identity: &IdentityIndex,
180	    id: &PackageId,
181	) -> Result<Option<&'a Package>, GraphError> {
182	    match identity.resolve_id(id) {
183	        Ok(resolved) => Ok(packages.into_iter().find(|p| p.id == resolved)),
184	        Err(GraphError::UnknownPackage { .. }) => Ok(None),
185	        Err(e) => Err(e),
186	    }
187	}
