189	#[allow(clippy::too_many_arguments)]
190	pub fn aggregate<D, I>(
191	    graph: &D,
192	    identity: &IdentityIndex,
193	    config: &ResolvedConfig,
194	    git: &GitAccess<'_>,
195	    tags: &TagIndex,
196	    base_versions: &BTreeMap<PackageId, Version>,
197	    pre: Option<&callisto_model::format::PreState>,
198	    inference: &I,
199	) -> Result<Aggregation, GraphError>
200	where
201	    D: DependencyResolver,
202	    I: SeverityInference,
203	{
204	    let loaded = load_changesets(&config.root, config)?;
205	    let mut agg = Aggregation::default();
206	
207	    for pkg in graph.packages() {
208	        let cur_sev = agg.severities.get(&pkg.id).copied().unwrap_or(Severity::None);
209	        let pathspecs: Vec<PathBuf> = crate::changed::package_paths(pkg);
210	        let last_tag = tags.last_tag(&pkg.id);
211	        let cur_ver = last_tag
212	            .map(|t| t.version.clone())
213	            .or_else(|| base_versions.get(&pkg.id).cloned())
214	            .ok_or_else(|| {
215	                GraphError::Manifest(callisto_model::ManifestError::MissingField {
216	                    path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
217	                    field: "version",
218	                })
219	            })?;
220	
221	        let package_ecosystems: Vec<Ecosystem> = pkg.canonical_manifests().map(|m| m.ecosystem()).collect();
222	        let policy = resolve_package_config(&pkg.id, &package_ecosystems, config)?
223	            .and_then(|pcfg| pcfg.pre_major_inference)
224	            .unwrap_or(PreMajorInferencePolicy::Off);
225	
226	        // release_trigger: Changeset packages take severity from pending changesets only --
227	        // commit inference must not run for them, so neither does resolving its window.
228	        let inferred = if pkg.release_trigger == ReleaseTrigger::Auto {
229	            let window = crate::infer::InferenceWindowSpec {
230	                pathspecs: &pathspecs,
231	                since: last_tag.and_then(|t| resolve_since(git, t.name.as_str())),
232	                current_version: &cur_ver,
233	                has_prior_release: last_tag.is_some(),
234	                policy,
235	            };
236	            inference.infer(pkg, git, window)
237	        } else {
238	            Ok(None)
239	        };
240	
241	        match inferred {
242	            Ok(Some(outcome)) => {
243	                if outcome.severity > cur_sev {
244	                    agg.severities.insert(pkg.id.clone(), outcome.severity);
245	                    agg.reasons.insert(
246	                        pkg.id.clone(),
247	                        BumpReason::Inference {
248	                            commits: outcome.commit_count,
249	                            remapped: outcome.remapped,
250	                        },
251	                    );
252	                    agg.named_by.insert(pkg.id.clone(), NamedBy::Inference);
253	                    agg.inference_commits.insert(pkg.id.clone(), outcome.commits.clone());
254	                }
255	            }
256	            Ok(None) => {}
257	            Err(e) => {
258	                agg.diagnostics.push(Diagnostic {
259	                    code: callisto_model::DiagnosticCode::PreMajorInferenceInert,
260	                    severity: callisto_model::DiagnosticSeverity::Warning,
261	                    message: format!("Commit inference failed for package `{}`: {e}", pkg.id.display_name()),
262	                    package: Some(pkg.id.clone()),
263	                    path: None,
264	                    governed_by: None,
265	                    escalated_by: None,
266	                });
267	            }
268	        }
269	    }
270	
271	    // During a pre-release cycle (PreMode::Pre) changesets must NOT be consumed:
272	    // they remain on disk so they can be re-applied when the cycle exits.
273	    let is_pre_mode = pre
274	        .map(|s| s.mode == callisto_model::format::PreMode::Pre)
275	        .unwrap_or(false);
276	    // Ids already recorded in pre.json still resolve for severity, but are not re-added to the changelog.
277	    let already_recorded: std::collections::HashSet<&str> = pre
278	        .map(|s| s.changesets.iter().map(String::as_str).collect())
279	        .unwrap_or_default();
280	
281	    for cs in loaded {
282	        let is_already_recorded = is_pre_mode && already_recorded.contains(cs.id.as_str());
283	        // Defer adding to `consumed` until after we confirm at least one entry
284	        // resolved to a real workspace package. A changeset where every entry
285	        // names a removed package must NOT be consumed (which would delete it
286	        // on disk); instead, an UnknownPackage diagnostic is emitted and the
287	        // file is left for the user to clean up manually.
288	        //
289	        // A changeset with a MIX of resolved and unresolved entries must also
290	        // stay unconsumed: consuming it would delete the file (or, in pre
291	        // mode, mark it as already-applied) and permanently lose the
292	        // unresolved entry's bump once that entry's target reappears.
293	        let mut matched_any = false;
294	        let mut has_unresolved = false;
295	        for entry in cs.changeset.entries {
296	            let id = match PackageId::parse(&entry.name) {
297	                Ok(id) => id,
298	                Err(_) => {
299	                    has_unresolved = true;
300	                    agg.diagnostics.push(Diagnostic {
301	                        code: callisto_model::DiagnosticCode::UnknownPackage,
302	                        severity: callisto_model::DiagnosticSeverity::Warning,
303	                        message: format!(
304	                            "Changeset `{}` contains invalid package name `{}`; the changeset \
305	                             will not be consumed until this entry is resolved",
306	                            cs.path.display(),
307	                            entry.name
308	                        ),
309	                        package: None,
310	                        path: Some(cs.path.clone()),
311	                        governed_by: None,
312	                        escalated_by: None,
313	                    });
314	                    continue;
315	                }
316	            };
317	            match resolve_target_package(graph.packages(), identity, &id)? {
318	                Some(target_pkg) => {
319	                    matched_any = true;
320	                    let canonical_id = target_pkg.id.clone();
