 66	pub fn status<R: CommandRunner, D: DependencyResolver, I: SeverityInference>(
 67	    ws: &Workspace<'_, R, D>,
 68	    inference: &I,
 69	    opts: &StatusOptions,
 70	) -> Result<StatusReport, GraphError> {
 71	    let mut packages = Vec::new();
 72	    let base_versions = ws.base_versions()?;
 73	    let (loaded_changesets, changeset_load_failures) = crate::load_changesets_permissive(&ws.root, &ws.config)?;
 74	    let tags = ws.tags()?;
 75	
 76	    let all_packages: Vec<&Package> = ws.graph.packages().collect();
 77	    let pending = resolve_pending_changesets(all_packages.iter().copied(), &loaded_changesets);
 78	
 79	    // Pending severity is `plan_version`'s own
 80	    // `PlannedBump.severity` per package -- the same cascade/fixed/linked-group
 81	    // computation `callisto version` uses. status computes no cascade of its
 82	    // own; it only reads the plan `plan_version` already derives.
 83	    let version_opts = VersionOptions {
 84	        strict: opts.strict,
 85	        allow_empty_changesets: true,
 86	    };
 87	    // An ambiguous changeset entry, or an unparseable changeset file, makes `plan_version`
 88	    // (via `aggregate`'s own strict `load_changesets`) hard-error -- the right behavior for a
 89	    // real `version`/`release` run, but `status` must survive both and report
 90	    // `AmbiguousPackageName`/the parse failure diagnostic below instead. Severity planning is
 91	    // skipped for this run rather than duplicating `aggregate`'s own resolution to route
 92	    // around its error.
 93	    let plan = match plan_version(ws, inference, &version_opts) {
 94	        Ok(plan) => Some(plan),
 95	        Err(GraphError::AmbiguousName { .. } | GraphError::ParseChangeset { .. }) => None,
 96	        Err(e) => return Err(e),
 97	    };
 98	    let planned_severity: BTreeMap<PackageId, Severity> = plan
 99	        .iter()
100	        .flat_map(|plan| &plan.bumps)
101	        .map(|b| (b.package.clone(), b.severity))
102	        .collect();
103	
104	    let changed = changed_since_last_tag(&all_packages, tags, ws.git_access())?;
105	
106	    for pkg in all_packages.iter().copied() {
107	        let current_version = base_versions.get(&pkg.id).cloned().ok_or_else(|| {
108	            GraphError::Manifest(callisto_model::ManifestError::MissingField {
109	                path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
110	                field: "version",
111	            })
112	        })?;
113	        let last = tags.last_tag(&pkg.id);
114	        let last_tag = last.map(|t| t.name.clone());
115	        let last_released_version = last.map(|t| t.version.clone());
116	
117	        let (pkg_changesets, _) = pending.get(&pkg.id).cloned().unwrap_or_default();
118	        let pending_severity = planned_severity.get(&pkg.id).copied();
119	
120	        packages.push(callisto_model::StatusPackageRecord {
121	            package: pkg.id.clone(),
122	            current_version,
123	            last_tag,
124	            last_released_version,
125	            pending_severity,
126	            changed_since_last_tag: changed[&pkg.id],
127	            release_trigger: pkg.release_trigger,
128	            pending_changesets: pkg_changesets,
129	        });
130	    }
131	
132	    let mut diagnostics = ws.graph.diagnostics().to_vec();
133	    // Fold in every well-formedness diagnostic `validate` used to
134	    // report (EmptyChangeset, UnknownPackage, AmbiguousPackageName,
135	    // InvalidPackageName) now that `validate` is gone.
136	    diagnostics.extend(changeset_wellformedness_diagnostics(
137	        all_packages.iter().copied(),
138	        &loaded_changesets,
139	    ));
140	    for failure in &changeset_load_failures {
141	        diagnostics.push(Diagnostic {
142	            code: DiagnosticCode::ChangesetParseFailed,
143	            severity: DiagnosticSeverity::Error,
144	            message: format!("{}: {}", failure.path.display(), failure.source),
145	            package: None,
146	            path: Some(failure.path.clone()),
147	            governed_by: None,
148	            escalated_by: None,
149	        });
150	    }
151	    escalate(&mut diagnostics, opts.strict);
152	
153	    let has_changesets = packages.iter().any(|p| !p.pending_changesets.is_empty());
154	    // Count of packages with a planned bump, post-cascade/fixed/linked-group --
155	    // the field a script now reads to detect pending changesets, since `--check`'s
156	    // exit code no longer signals it.
157	    let pending = packages.iter().filter(|p| p.pending_severity.is_some()).count() as u32;
158	
159	    Ok(StatusReport {
160	        schema_version: SCHEMA_VERSION,
161	        has_changesets,
162	        pending,
163	        packages,
164	        diagnostics,
165	    })
166	}
