168	/// The per-changeset well-formedness diagnostics `validate` used to emit
169	/// (crates/callisto-graph/src/commands/validate.rs, now removed): entries shape and
170	/// package-name resolution. Uses the same `resolve_unique` primitive
171	/// `resolve_pending_changesets` does, but this scan must never abort early,
172	/// so an unknown or ambiguous entry becomes a diagnostic instead of an
173	/// early return.
174	///
175	/// An entries-empty changeset is advisory only (`Info`): `@changesets/cli add --empty`
176	/// produces one deliberately, so it is not a well-formedness problem. A changeset with
177	/// entries but an empty summary never reaches this scan at all -- `load_changesets_permissive`
178	/// already rejects that shape at parse time, surfacing it as a `ChangesetParseFailed`
179	/// diagnostic instead.
180	fn changeset_wellformedness_diagnostics<'a>(
181	    packages: impl Iterator<Item = &'a Package> + Clone,
182	    loaded: &[LoadedChangeset],
183	) -> Vec<Diagnostic> {
184	    let mut diagnostics = Vec::new();
185	    for cs in loaded {
186	        if cs.changeset.entries.is_empty() {
187	            diagnostics.push(Diagnostic {
188	                code: DiagnosticCode::EmptyChangeset,
189	                severity: DiagnosticSeverity::Info,
190	                message: format!("Changeset `{}` is empty", cs.path.display()),
191	                package: None,
192	                path: Some(cs.path.clone()),
193	                governed_by: None,
194	                escalated_by: None,
195	            });
196	        }
197	
198	        for entry in &cs.changeset.entries {
199	            match PackageId::parse(&entry.name) {
200	                Ok(id) => match id.resolve_unique(packages.clone(), |p| &p.id) {
201	                    Ok(None) => {
202	                        diagnostics.push(Diagnostic {
203	                            code: DiagnosticCode::UnknownPackage,
204	                            severity: DiagnosticSeverity::Error,
205	                            message: format!(
206	                                "Changeset `{}` references unknown package `{}`",
207	                                cs.path.display(),
208	                                entry.name
209	                            ),
210	                            package: Some(id),
211	                            path: Some(cs.path.clone()),
212	                            governed_by: None,
213	                            escalated_by: None,
214	                        });
215	                    }
216	                    Ok(Some(_)) => {}
217	                    Err(candidates) => {
218	                        let names: Vec<String> = candidates.iter().map(|p| p.id.display_name().to_string()).collect();
219	                        diagnostics.push(Diagnostic {
220	                            code: DiagnosticCode::AmbiguousPackageName,
130	            CascadeBumpSeverity::Patch => Severity::Patch,
131	            CascadeBumpSeverity::Minor => Severity::Minor,
132	        }
133	    }
134	}
