 95	    pub(crate) fn validate_syntactic(raw: &RawGroupTable) -> Result<(), ConfigError> {
 96	        let mut seen_names = BTreeSet::new();
 97	        for group_list in [&raw.fixed, &raw.linked] {
 98	            for g in group_list {
 99	                if !seen_names.insert(&g.name) {
100	                    return Err(ConfigError::DuplicateGroupName { group: g.name.clone() });
101	                }
102	                if g.members.is_empty() {
103	                    return Err(ConfigError::EmptyGroup { group: g.name.clone() });
104	                }
105	            }
106	        }
107	
108	        // One map, populated fixed-then-linked (declaration order, not file
109	        // order): a fixed group's members are checked only against other
110	        // fixed groups seen so far (linked hasn't been touched yet at that
111	        // point), while a linked group's members are checked against BOTH
112	        // linked-so-far AND the now-fully-populated fixed map -- exactly the
113	        // asymmetric cross-check the two-separate-maps version encoded, but
114	        // as a natural consequence of processing order instead of a second
115	        // explicit lookup.
116	        let mut claimed: BTreeMap<&str, &GroupName> = BTreeMap::new();
117	        for group_list in [&raw.fixed, &raw.linked] {
118	            for g in group_list {
119	                for m in &g.members {
120	                    if let Some(other) = claimed.insert(m.as_str(), &g.name) {
121	                        if other == &g.name {
122	                            return Err(ConfigError::DuplicateMemberInGroup {
123	                                group: g.name.clone(),
124	                                member: m.clone(),
125	                            });
126	                        }
127	                        return Err(ConfigError::ConflictingGroupNames {
128	                            group: g.name.clone(),
129	                            other: other.clone(),
130	                            member: m.clone(),
131	                        });
132	                    }
133	                }
134	            }
135	        }
