   140	    pub(crate) fn resolve(raw: &RawGroupTable, index: &IdentityIndex) -> Result<GroupTable, GraphError> {
   141	        let mut fixed = BTreeMap::new();
   142	        let mut linked = BTreeMap::new();
   143	        let mut fixed_of = BTreeMap::new();
   144	        let mut linked_of = BTreeMap::new();
   145	        let mut claimed_by: BTreeMap<PackageId, GroupName> = BTreeMap::new();
   146	
   147	        // One resolution loop parameterized on `GroupKind`, writing into
   148	        // whichever kind's own output maps -- `claimed_by` is shared across
   149	        // both passes exactly as before, so a package claimed by a fixed
   150	        // group still conflicts if a linked group (or a second fixed group)
   151	        // also claims it.
   152	        for (kind, raw_groups, groups, membership) in [
   153	            (GroupKind::Fixed, &raw.fixed, &mut fixed, &mut fixed_of),
   154	            (GroupKind::Linked, &raw.linked, &mut linked, &mut linked_of),
   155	        ] {
   156	            for rg in raw_groups {
   157	                let mut members = Vec::new();
   158	                for name in &rg.members {
   159	                    // Platform manifests take priority: their own native name
   160	                    // is also registered in `index.native` (pointing at their
   161	                    // owner), so `index.resolve` would otherwise resolve them
   162	                    // to `GroupMember::Package(owner)` and silently drop the
   163	                    // platform-manifest membership version.rs's platform-write
   164	                    // derivation depends on.
   165	                    if let Some((owner, path, role)) = index.platform.get(name) {
   166	                        members.push(GroupMember::PlatformManifest {
   167	                            owner: owner.clone(),
   168	                            role: role.clone(),
   169	                            path: path.clone(),
   170	                            name: name.clone(),
   171	                        });
   172	                        continue;
   173	                    }
   174	                    match index.resolve(name) {
   175	                        Ok(id) => {
   176	                            if let Some(other) = claimed_by.get(&id) {
   177	                                if other != &rg.name {
   178	                                    return Err(GraphError::ConflictingGroupMembership {
   179	                                        package: id.clone(),
   180	                                        groups: vec![other.clone(), rg.name.clone()],
   181	                                    });
   182	                                }
   183	                            } else {
   184	                                claimed_by.insert(id.clone(), rg.name.clone());
   185	                            }
   186	                            members.push(GroupMember::Package(id.clone()));
   187	                            membership.insert(id, rg.name.clone());
   188	                        }
