   258	/// The one package among `candidates` whose canonical manifest existed at `rev`, if exactly one did: the owner
   259	/// of anything recorded under their shared bare name at that point.
   260	pub(crate) fn sole_owner_at<'p>(
   261	    git: &GitAccess<'_>,
   262	    rev: &str,
   263	    candidates: &[&'p callisto_model::Package],
   264	) -> Result<Option<&'p callisto_model::Package>, GraphError> {
   265	    let mut owner = None;
   266	    for pkg in candidates {
   267	        let Some(manifest) = pkg.canonical_manifests().next() else {
   268	            continue;
   269	        };
   270	        if git.path_exists_at(rev, &manifest.path).map_err(GraphError::Vcs)? {
   271	            if owner.is_some() {
   272	                return Ok(None);
   273	            }
   274	            owner = Some(*pkg);
   275	        }
   276	    }
   277	    Ok(owner)
   278	}
