     3	
     4	/// A glob pattern for matching package names in `[[package-set]]` blocks.
     5	///
     6	/// Unlike `[[package]]` which uses an exact `PackageId` match,
     7	/// `[[package-set]]` allows a single rule to target many packages at once
     8	/// via a glob (e.g. `"pkg-*"` matches `pkg-a`, `pkg-b`, etc.).
     9	///
    10	/// Ecosystem prefixes in the pattern are respected: `"cargo:pkg-*"` only
    11	/// matches Cargo packages; a bare `"pkg-*"` matches packages in any ecosystem
    12	/// that have a matching name.
    13	#[derive(Clone, Debug)]
    14	pub struct PackagePattern {
    15	    raw: String,
    16	    /// The ecosystem parsed off the front of the pattern (e.g. `cargo` in
    17	    /// `"cargo:pkg-*"`), or `None` for a bare pattern like `"pkg-*"`.
    18	    ecosystem: Option<Ecosystem>,
    19	    /// Compiled from the pattern with any `ecosystem:` prefix stripped.
    20	    matcher: GlobMatcher,
    21	}
    22	
    23	impl PackagePattern {
    24	    pub fn parse(s: &str) -> Result<Self, globset::Error> {
    25	        // Try `:` first so `cargo:pkg-*` keeps its existing meaning, then `/`
    26	        // so `cargo/pkg-*` is accepted too, matching `PackageId::parse`'s two
    27	        // qualified forms.
    28	        let (ecosystem, rest) = [':', '/']
    29	            .into_iter()
    30	            .find_map(|sep| {
    31	                let (prefix, rest) = s.split_once(sep)?;
    32	                Ecosystem::from_prefix(prefix).map(|eco| (Some(eco), rest))
    33	            })
    34	            .unwrap_or((None, s));
    35	        let glob = Glob::new(rest)?;
    36	        Ok(Self {
    37	            raw: s.to_string(),
    38	            ecosystem,
    39	            matcher: glob.compile_matcher(),
    40	        })
    41	    }
    42	
    43	    /// Returns the ecosystem this pattern was scoped to via an
    44	    /// `ecosystem:` prefix, or `None` for a bare pattern.
    45	    pub fn ecosystem(&self) -> Option<Ecosystem> {
    46	        self.ecosystem
    47	    }
    48	
    49	    /// Returns true when the given `PackageId` matches this pattern.
    50	    ///
    51	    /// A bare pattern (no `ecosystem:` prefix) matches any ecosystem, so
    52	    /// `"pkg-*"` matches both `cargo:pkg-a` and `npm:pkg-b`. An
    53	    /// ecosystem-prefixed pattern like `"cargo:pkg-*"` matches only packages
    54	    /// in that ecosystem — `id.ecosystem()` must equal the parsed prefix
    55	    /// before the glob remainder is compared against `id.name()`.
    56	    pub fn matches(&self, id: &PackageId) -> bool {
    57	        self.matches_in_ecosystems(id.name(), id.ecosystem().as_slice())
    58	    }
    59	
    60	    /// Like [`Self::matches`], but checks a name against an explicit set of
    61	    /// candidate ecosystems rather than a single `PackageId`.
    62	    ///
    63	    /// This is needed at walk time: discovered package ids are
    64	    /// [`PackageId::Bare`] (no ecosystem attached to the id itself), so the
    65	    /// real ecosystem(s) of the package — sourced from its manifests — must
    66	    /// be supplied explicitly for an ecosystem-prefixed pattern to ever be
    67	    /// able to match.
    68	    pub fn matches_in_ecosystems(&self, name: &str, ecosystems: &[Ecosystem]) -> bool {
    69	        if let Some(want) = self.ecosystem {
    70	            if !ecosystems.contains(&want) {
    71	                return false;
    72	            }
    73	        }
    74	        self.matcher.is_match(name)
    75	    }
