   275	fn write_facts(facts: &InitFacts, out: &mut dyn Write) -> Result<(), CliError> {
   276	    let ecosystems: Vec<&str> = facts.ecosystems.iter().map(|ecosystem| ecosystem.prefix()).collect();
   277	    writeln!(out, "Detected:")?;
   278	    writeln!(out, "  ecosystems: {}", ecosystems.join(", "))?;
   279	    writeln!(out, "  origin: {}", facts.origin.as_deref().unwrap_or("none"))?;
   280	    writeln!(out, "  packages:")?;
   281	    for package in &facts.packages {
   282	        let tag = package.last_tag.as_ref().map_or("none", |tag| tag.as_str());
   283	        write!(out, "    {} {} (last tag: {tag}", package.id, package.version)?;
   284	        if package.is_binary() {
   285	            write!(out, "; binary: {}", package.bin_names.join(", "))?;
   286	        }
   287	        writeln!(out, ")")?;
   288	    }
   289	    Ok(())
   290	}
